package app.roadstr.core.protocol.interop

import app.roadstr.core.protocol.nostr.BoundedJsonParser
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test

/**
 * Runs every vector of docs/interoperability/vectors/road-events-v1.json, the conformance file of
 * nips/road-events.md (jooray/roadbeacon), generated by an independent implementation. Nothing in
 * it is computed by this codec, so a mismatch here is a mismatch with the other clients.
 */
class CompactRoadCodecVectorsTest {
    @Suppress("UNCHECKED_CAST")
    private val root: Map<String, Any?> by lazy {
        val stream = requireNotNull(javaClass.getResourceAsStream("/road-events-v1.json")) {
            "vectors file is not on the test classpath"
        }
        BoundedJsonParser(stream.bufferedReader(Charsets.UTF_8).use { it.readText() }).parse() as Map<String, Any?>
    }

    @Suppress("UNCHECKED_CAST")
    private fun section(name: String): List<Map<String, Any?>> {
        val rows = root[name] as List<Map<String, Any?>>
        assertTrue("section $name is empty", rows.isNotEmpty())
        return rows
    }

    @Suppress("UNCHECKED_CAST")
    private fun Map<String, Any?>.event(): Map<String, Any?> = this["event"] as Map<String, Any?>

    private fun Map<String, Any?>.frame(): ByteArray = hexToBytes(this["frame"] as String)

    private fun Map<String, Any?>.label(): String = this["name"] as String

    @Test
    fun `the limits are the ones this codec enforces`() {
        @Suppress("UNCHECKED_CAST")
        val limits = root["limits"] as Map<String, Any?>
        assertEquals(1L, root["version"])
        assertEquals(CompactRoadCodec.REPORT_BASE_SIZE.toLong(), limits["report_base"])
        assertEquals(CompactRoadCodec.REPORT_MAX_ENCODED_SIZE.toLong(), limits["report_max_encode"])
        assertEquals(CompactRoadCodec.REPORT_MAX_SIZE.toLong(), limits["report_max_decode"])
        assertEquals(CompactRoadCodec.MAX_ENCODED_COMMENT_BYTES.toLong(), limits["max_comment_encode"])
        assertEquals(CompactRoadCodec.MAX_COMMENT_BYTES.toLong(), limits["max_comment_decode"])
        assertEquals(CompactRoadCodec.CONFIRMATION_SIZE.toLong(), limits["vote"])
    }

    @Test
    fun `valid vectors encode to the exact frame and decode to the exact event`() {
        for (vector in section("valid")) {
            val event = vector.event()
            when (val encoded = encode(event)) {
                is CompactOutcome.Ok -> assertEquals(vector.label(), vector["frame"], toHex(encoded.value))
                is CompactOutcome.Failed -> fail("${vector.label()}: encoder refused with ${encoded.error}")
            }
            assertDecodesTo(vector.label(), vector.frame(), event)
        }
    }

    @Test
    fun `decode-only vectors decode exactly, and over-long comments are never encoded`() {
        for (vector in section("decode_only")) {
            val event = vector.event()
            assertDecodesTo(vector.label(), vector.frame(), event)
            val commentBytes = (event["content"] as String).toByteArray(Charsets.UTF_8).size
            if (commentBytes > CompactRoadCodec.MAX_ENCODED_COMMENT_BYTES) {
                assertEquals(vector.label(), CompactError.COMMENT_TOO_LONG, (encode(event) as CompactOutcome.Failed).error)
            }
        }
    }

    @Test
    fun `decode-invalid vectors are refused with the exact error`() {
        for (vector in section("decode_invalid")) {
            val outcome = CompactRoadCodec.decode(vector.frame())
            val error = (outcome as? CompactOutcome.Failed)?.error
            assertEquals(vector.label(), vector["error"], error?.name)
        }
    }

    @Test
    fun `encode-invalid vectors are refused with the exact error`() {
        for (vector in section("encode_invalid")) {
            val error = (encode(vector.event()) as? CompactOutcome.Failed)?.error
            assertEquals(vector.label(), vector["error"], error?.name)
        }
    }

    private fun encode(event: Map<String, Any?>): CompactOutcome<ByteArray> =
        if ((event["kind"] as? Number)?.toInt() == CompactRoadCodec.KIND_CONFIRMATION) {
            CompactRoadCodec.encodeConfirmation(event)
        } else {
            CompactRoadCodec.encodeReport(event)
        }

    private fun assertDecodesTo(label: String, frame: ByteArray, expected: Map<String, Any?>) {
        val decoded = when (val outcome = CompactRoadCodec.decode(frame)) {
            is CompactOutcome.Ok -> outcome.value.event
            is CompactOutcome.Failed -> return fail("$label: decoder refused with ${outcome.error}")
        }
        for (field in listOf("id", "pubkey", "tags", "content", "sig")) {
            assertEquals("$label: $field", expected[field], decoded[field])
        }
        assertEquals("$label: created_at", (expected["created_at"] as Number).toLong(), (decoded["created_at"] as Number).toLong())
        assertEquals("$label: kind", (expected["kind"] as Number).toInt(), (decoded["kind"] as Number).toInt())
    }

    private fun hexToBytes(hex: String): ByteArray =
        ByteArray(hex.length / 2) { index -> hex.substring(index * 2, index * 2 + 2).toInt(16).toByte() }

    private fun toHex(bytes: ByteArray): String = bytes.joinToString("") { "%02x".format(it) }
}
